from common import *

def room():
    c1 = calc('c1', "A diatomic chain: acoustic and optical branches", 'normal',
      "Script 2.2.5: $N$ cells of lattice constant $a$, two atoms per cell (masses $M_1,M_2$ at fractional positions $0$ and $\\frac12$), nearest-neighbour springs $k$, longitudinal motion. The dispersion is $\\omega^2=k\\big(\\tfrac1{M_1}+\\tfrac1{M_2}\\big)\\pm k\\sqrt{\\big(\\tfrac1{M_1}+\\tfrac1{M_2}\\big)^2-\\tfrac{2}{M_1M_2}(1-\\cos qa)}$. Take a toy NaCl chain: $M_1=22.99\\,$u (Na), $M_2=35.45\\,$u (Cl), $k=15$ N/m, $a=5.64$ Å. Give frequencies as $\\nu=\\omega/2\\pi$ in THz.",
      V('u', M1=22.99, M2=35.45, k=15.0, a=5.64e-10),
      [step('nuopt0', "Optical branch at $q=0$: $\\omega=\\sqrt{2k(1/M_1+1/M_2)}$. Give $\\nu$ in THz.", "sqrt(2*k*(1/(M1*u)+1/(M2*u)))/(2*pi)/1e12", "THz", ["THz", "rad/s", "meV", "m/s"], 0.02,
            "At $q=0$: $(1-\\cos qa)=0$, the root is $2k(1/M_1+1/M_2)$ (plus sign) or 0 (acoustic). The two atoms in the cell move against each other."),
       step('nuac', "Acoustic branch at the zone edge $q=\\pi/a$ (the upper end of the acoustic branch is set by the **heavier** mass): $\\nu=\\frac1{2\\pi}\\sqrt{2k/M_2}$ in THz.", "sqrt(2*k/(M2*u))/(2*pi)/1e12", "THz", ["THz", "rad/s", "meV", "m/s"], 0.02,
            "At $q=\\pi/a$, $1-\\cos qa=2$ and the square root becomes $k|1/M_1-1/M_2|$, so $\\omega^2=2k/M_{\\max}$ (acoustic) and $2k/M_{\\min}$ (optical)."),
       step('nuop', "Optical branch at $q=\\pi/a$: $\\nu=\\frac1{2\\pi}\\sqrt{2k/M_1}$ in THz.", "sqrt(2*k/(M1*u))/(2*pi)/1e12", "THz", ["THz", "rad/s", "meV", "m/s"], 0.02,
            "Lighter atom oscillates against a nearly still heavy neighbour."),
       step('gap', "Frequency gap at the zone boundary in THz (nothing propagates in the gap).", "nuop-nuac", "THz", ["THz", "meV", "rad/s", "m/s"], 0.05,
            "$\\Delta\\propto 1/\\sqrt{M_1}-1/\\sqrt{M_2}\\to0$ for $M_1\\to M_2$: then the zone folds and one branch remains (script, Fig. 2.2). At the boundary both group velocities vanish: $\\omega(q)=\\omega(-q)$ and $\\omega(q+2\\pi/a)=\\omega(q)$ force $d\\omega/dq=0$ at $q=\\pi/a$."),
       step('v', "Sound velocity from the small-$q$ acoustic branch $\\omega\\approx vq$ with $v=a\\sqrt{k/[2(M_1+M_2)]}$, in m/s.", "a*sqrt(k/(2*(M1+M2)*u))", "m/s", ["m/s", "THz", "km/s^2", "m"], 0.02,
            "Expand $\\omega^2\\approx\\frac{k\\,a^2}{2(M_1+M_2)}q^2$. Check: for $M_1=M_2=M$ this is $(a/2)\\sqrt{k/M}$, the monatomic chain with spacing $a/2$."),
       step('hbarw', "Energy $\\hbar\\omega$ of the optical $q=0$ phonon in meV (this is what inelastic neutron scattering measures).", "nuopt0*1e12*2*pi*hbar/eV*1e3", "meV", ["meV", "eV", "THz", "K"], 0.02,
            "$\\hbar\\omega=h\\nu$; 1 THz = 4.136 meV. Thermal neutrons ($\\sim25$ meV) match phonon energies.", bonus=True)],
      70)

    c2 = calc('c2', "Copper: where do phonons stop mattering?", 'normal',
      "Copper has $n=8.47\\times10^{28}$ m$^{-3}$ atoms, one conduction electron each, and Debye temperature $T_D=343$ K (script 2.4). Free-electron gas: $c_{\\rm el}=\\frac{\\pi^2}{3}\\nu(\\epsilon_F)k_B^2T=\\gamma T$ with $\\nu(\\epsilon_F)=\\frac{3n}{2\\epsilon_F}$. Debye low-$T$ law (script 2.79): $c_{\\rm ph}=\\frac{12\\pi^4}{5}\\,nk_B\\,(T/T_D)^3=\\beta T^3$. Find the temperature where both contribute equally.",
      V('kB', n=8.47e28, TD=343.0),
      [step('DP', "Dulong–Petit limit $3nk_B$ of the lattice heat capacity per volume, in J m$^{-3}$ K$^{-1}$.", "3*n*kB", "J/(m^3 K)", ["J/(m^3 K)", "J/(m^3 K^2)", "J/(m^3 K^4)", "J/K"], 0.01,
            "Classical equipartition: $3k_B$ per atom, valid for $T\\gtrsim T_D$ (script 2.80)."),
       step('EF', "Free-electron Fermi energy $\\epsilon_F=\\hbar^2(3\\pi^2n)^{2/3}/2m_e$ in eV.", "hbar**2*(3*pi**2*n)**(2/3)/(2*me)/eV", "eV", ["eV", "meV", "J", "K"], 0.02,
            "$k_F=(3\\pi^2n)^{1/3}=1.36$ Å$^{-1}$, $\\hbar^2/2m_e=3.81$ eV Å$^2$. One electron per atom."),
       step('gam', "Electronic coefficient $\\gamma=\\frac{\\pi^2}{2}\\,\\frac{nk_B^2}{\\epsilon_F}$ in J m$^{-3}$ K$^{-2}$.", "pi**2/2*n*kB**2/(EF*eV)", "J/(m^3 K^2)", ["J/(m^3 K^2)", "J/(m^3 K)", "J/(m^3 K^4)", "J/K"], 0.02,
            "$\\frac{\\pi^2}{3}\\nu k_B^2=\\frac{\\pi^2}{3}\\frac{3n}{2\\epsilon_F}k_B^2$. Only electrons within $k_BT$ of $\\epsilon_F$ (a fraction $T/T_F$) can absorb heat."),
       step('beta', "Phonon coefficient $\\beta=\\frac{12\\pi^4}{5}nk_B/T_D^3$ in J m$^{-3}$ K$^{-4}$.", "12*pi**4/5*n*kB/TD**3", "J/(m^3 K^4)", ["J/(m^3 K^4)", "J/(m^3 K^2)", "J/(m^3 K)", "J/K"], 0.02,
            "$12\\pi^4/5=233.8$. Debye assumes $\\nu(\\epsilon)\\propto\\epsilon^2$ up to a cutoff that holds $3N$ modes."),
       step('Tx', "Crossover temperature $\\gamma T=\\beta T^3$, i.e. $T_\\times=\\sqrt{\\gamma/\\beta}$, in K.", "sqrt(gam/beta)", "K", ["K", "mK", "eV", "K^2"], 0.03,
            "Below $T_\\times$ electrons dominate $C_V\\propto T$; above it phonons $\\propto T^3$. Plotting $C/T$ against $T^2$ gives a straight line with intercept $\\gamma$ and slope $\\beta$. Here $T_\\times\\approx3$ K, well inside the $T^3$ regime ($T<T_D/50\\approx7$ K).")],
      70)

    c3 = calc('c3', "Einstein versus Debye at low temperature", 'normal',
      "A solid has a single Einstein temperature $\\Theta_E=300$ K (all $3N$ modes at one frequency, $\\nu(\\epsilon)\\propto\\delta(\\hbar\\omega_E-\\epsilon)$) and, in the Debye model, $T_D=300$ K. Heat capacity as a fraction of $3Nk_B$: Einstein $f_E(x)=x^2e^x/(e^x-1)^2$ with $x=\\Theta_E/T$; Debye low-$T$: $f_D=\\frac{4\\pi^4}{5}(T/T_D)^3$ (this is $C_V/3Nk_B$; the script's (2.79) $C_V=\\frac{12\\pi^4}{5}Nk_B(T/T_D)^3$ divided by the Dulong–Petit value $3Nk_B$).",
      dict(ThetaE=300.0, TD=300.0, T1=100.0, T2=15.0),
      [step('x1', "At $T_1=100$ K: $x=\\Theta_E/T_1$.", "ThetaE/T1", "dimensionless", ["dimensionless", "K", "eV", "K^-1"], 0.01,
            "Ratio of the oscillator quantum to $k_BT$."),
       step('fE1', "Einstein heat capacity fraction $f_E$ at $T_1$.", "x1**2*exp(x1)/(exp(x1)-1)**2", "dimensionless", ["dimensionless", "J/K", "K", "eV"], 0.02,
            "At $x=3$ about half of the classical Dulong–Petit value: the oscillators are partly frozen out."),
       step('fD2', "Debye $T^3$ fraction $f_D$ at $T_2=15$ K ($T_2/T_D=0.05$).", "4*pi**4/5*(T2/TD)**3", "dimensionless", ["dimensionless", "J/K", "K", "eV"], 0.02,
            "$\\frac{4\\pi^4}{5}=77.9$, so $77.9\\times(0.05)^3=0.0097$: about 1 % of the classical value (and the exact Debye function agrees). The $T^3$ law needs only the **linear** acoustic dispersion at small $q$."),
       step('fE2', "Einstein fraction $f_E$ at $T_2$ ($x=20$).", "(ThetaE/T2)**2*exp(ThetaE/T2)/(exp(ThetaE/T2)-1)**2", "dimensionless", ["dimensionless", "J/K", "K", "eV"], 0.05,
            "For $x\\gg1$: $f_E\\to x^2e^{-x}$, an activated (exponential) freeze-out: far too fast. Einstein's model has a gap at $\\epsilon=\\hbar\\omega_E$, real solids have gapless acoustic phonons."),
       step('rat', "How many times larger is the Debye value than the Einstein value at $T_2$? (quick estimate within 25 %)", "fD2/fE2", "dimensionless", ["dimensionless", "K", "eV", "J/K"], 0.1,
            "That is why Einstein's 1907 model failed experiment at low $T$ and Debye's gives the $T^3$ law. Einstein remains the right tool for flat optical branches (script 2.4.2).", tolType='log')],
      60)

    c4 = calc('c4', "Why neutrons and not X-rays?", 'fermi',
      "Quick fight. Phonon energies are of order 10 meV, and inelastic scattering needs the probe energy to be comparable. Take a thermal neutron with the exam's $\\lambda=2.36$ Å ($\\hbar^2k^2/2m_n$) and compare it with an X-ray photon of the same wavelength ($E=hc/\\lambda$). Ratio in a factor of 1.3.",
      V('h', 'c', 'mn', lam=2.36e-10),
      [step('En', "Neutron energy in meV.", "(h/lam)**2/(2*mn)/eV*1e3", "meV", ["meV", "eV", "keV", "K"], 0.03,
            "$E=p^2/2m_n$ with $p=h/\\lambda$. Handy: $E[{\\rm meV}]\\approx81.8/\\lambda[\\text{Å}]^2$."),
       step('Ex', "X-ray photon energy in keV.", "h*c/lam/eV/1e3", "keV", ["keV", "meV", "eV", "MeV"], 0.03,
            "$E[{\\rm keV}]=12.398/\\lambda[\\text{Å}]$."),
       step('R', "$E_X/E_n$.", "Ex*1e3*1e3/En", "dimensionless", ["dimensionless", "eV", "keV", "K"], 0.1,
            "A $10$ meV phonon changes a 5 keV photon's energy by one part in $5\\times10^5$: practically unresolvable. For neutrons the same energy transfer is a $\\sim70\\%$ effect. Same wavelength (atomic spacing), very different energy: the neutron is the phonon probe. Bridge to QM: de Broglie $\\lambda=h/p$.", tolType='log')],
      20)

    boss1 = boss('b1', "Boss: the diatomic chain (constructed in exam style)",
      dict(file="notes/solid-state/02-phonons-and-heat.md", where="constructed from script 2.2.5 and Debye/Einstein 2.4; oral protocols HS04, HS05, HS14 (materials/solid-state/old-exams) show the chain, Debye model and neutron scattering as the recurring phonon questions. Not a verbatim past exam."),
      30,
      "No written phonon problem exists in the recent exams, so this one is built from the script derivation and the oral-exam checklist. Do it on paper, then check the numbers.",
      ["A one-dimensional crystal has two atoms per unit cell of length $a$, with masses $M_1=M$ and $M_2=3M$, coupled only to nearest neighbours by springs of constant $k$.",
       "(a) [5 pt] Write the equations of motion for the displacements $\\rho_{i,1},\\rho_{i,2}$ and derive the dispersion $\\omega^2(q)$ with the plane-wave ansatz.",
       "(b) [3 pt] Sketch both branches over $-2\\pi/a<q<2\\pi/a$. Mark the first Brillouin zone and the group velocity at $q=\\pi/a$. Why does it vanish?",
       "(c) [4 pt] Give $\\omega$ of the acoustic and optical branches at $q=0$ and $q=\\pi/a$ in units of $\\sqrt{k/M}$. For $q\\to0$ describe the atomic motion in both branches.",
       "(d) [3 pt] What happens to the gap at $q=\\pi/a$ for $M_2\\to M_1$? Explain through the folding of the Brillouin zone.",
       "(e) [3 pt] The crystal is probed by inelastic neutron scattering with $\\lambda=2.36$ Å. Why can this energy window resolve $\\hbar\\omega(q)$?"],
      [fa('wac', "(c) $\\omega_{\\rm ac}(\\pi/a)$ in units of $\\sqrt{k/M}$.", "sqrt(2/3)", dict(), 0.01),
       fa('wop', "(c) $\\omega_{\\rm opt}(\\pi/a)$ in units of $\\sqrt{k/M}$.", "sqrt(2)", dict(), 0.01),
       fa('wop0', "(c) $\\omega_{\\rm opt}(0)$ in units of $\\sqrt{k/M}$.", "sqrt(2*(1+1/3))", dict(), 0.01),
       fa('ratio', "(c) $\\omega_{\\rm opt}(0)/\\omega_{\\rm ac}(\\pi/a)$.", "sqrt((1+1/3)/(1/3))", dict(), 0.01),
       fa('vs', "(c) Sound velocity $v=\\lim\\omega/q$ in units of $a\\sqrt{k/M}$.", "sqrt(1/(2*(1+3)))", dict(), 0.01)],
      ["(a) $M_1\\ddot\\rho_{i,1}=-k(2\\rho_{i,1}-\\rho_{i,2}-\\rho_{i-1,2})$ and $M_2\\ddot\\rho_{i,2}=-k(2\\rho_{i,2}-\\rho_{i,1}-\\rho_{i+1,1})$; ansatz $\\rho_{i,\\alpha}=A_\\alpha e^{i(qia-\\omega t)}/\\sqrt{M_\\alpha}$ gives the $2\\times2$ dynamical matrix $D$ with $D_{11}=2k/M_1$, $D_{22}=2k/M_2$, $D_{12}=-k(1+e^{iqa})/\\sqrt{M_1M_2}$, and $\\det(D-\\omega^2)=0$.",
       "(a) Result: $\\omega^2=k(\\frac1{M_1}+\\frac1{M_2})\\pm k\\sqrt{(\\frac1{M_1}+\\frac1{M_2})^2-\\frac{2}{M_1M_2}(1-\\cos qa)}$.",
       "(b) The acoustic branch starts at 0, the optical at $\\omega_{\\rm opt}(0)$. Both flatten at $q=\\pi/a$ because $\\omega(q)=\\omega(-q)$ and $\\omega(q)=\\omega(q+2\\pi/a)$, so $d\\omega/dq=0$ at the zone edge (standing waves, Bragg reflection of the phonon).",
       "(c) $q=0$: acoustic 0, optical $\\sqrt{2(1+1/3)}\\sqrt{k/M}=1.63\\sqrt{k/M}$; $q=\\pi/a$: acoustic $\\sqrt{2k/M_2}=0.82\\sqrt{k/M}$, optical $\\sqrt{2k/M_1}=1.41\\sqrt{k/M}$. Acoustic at $q\\to0$: both atoms in phase (sound wave); optical: the two atoms of a cell move against each other, centre of mass at rest.",
       "(d) The gap $\\propto|1/\\sqrt{M_1}-1/\\sqrt{M_2}|$ closes: the cell has halved to $a/2$ with one atom per cell, the Brillouin zone doubles, and the two branches are one branch in the extended zone (Fig. 2.2). Same story for a dimerisation: the gap opens as the cell doubles.",
       "(e) $\\lambda=2.36$ Å gives $E_n\\approx15$ meV, matching $\\hbar\\omega$ of phonons (10–100 meV) while its momentum $2\\pi/\\lambda\\approx2.7$ Å$^{-1}$ is large compared with $\\pi/a$: the transfers of both energy and momentum can be read off. X-rays of the same $\\lambda$ have keV energy: the phonon energy is far below the resolution."],
      90)

    return dict(file='phonon-halls', id='ss-phonon-halls', region="Solid State Crystal Caverns", title="The Phonon Halls", course="solid-state",
      topics=["diatomic chain, acoustic/optical branches", "group velocity at the zone boundary", "Bose–Einstein phonons, density of states", "Debye T^3 law, Dulong–Petit, Einstein model", "electrons vs phonons in C_V", "inelastic neutron scattering"],
      sources=[dict(file="materials/solid-state/scripts/Script-2026_2026-09-01.pdf", where="Ch. 2.2.5 (pp. 45–48 diatomic chain, zone folding), Ch. 2.3–2.4 (pp. 52–65 phonon gas, DOS, Debye, Einstein, C_V)"),
               dict(file="materials/solid-state/old-exams/HS20.pdf", where="MC (i) phonon branches NaCl, (k) volume halved, (l) Einstein model"),
               dict(file="materials/solid-state/old-exams/HS23 (1).pdf", where="Problem 2b (e)-(i): phonon DOS, Debye temperature, Grüneisen (used in the Drift Corridor boss)"),
               dict(file="materials/solid-state/old-exams/HS05.pdf", where="oral protocol: dispersion of the monatomic chain; also HS04 (specific heat, DOS), HS14"),
               dict(file="notes/solid-state/02-phonons-and-heat.md", where="transcription, formulas and checks")],
      links=[dict(course="qm", room="harmonic-oscillator-elevator", why="Every normal mode is a quantum harmonic oscillator: $E=\\hbar\\omega(n+\\frac12)$. The Einstein solid is $3N$ copies of the QM oscillator; Debye adds a spectrum of $\\omega$."),
             dict(course="astro", room="photometry-radiation", why="Debye's $T^3$ law is Planck's $T^4$ energy density for a gas of bosons with $\\omega=vq$: phonons ($3$ polarisations, speed $v$) versus photons ($2$, speed $c$). See the Degenerate Core room.")],
      intro="Beneath the caverns the atoms ring like bells. Solve the two-atom chain for its acoustic and optical branches, count phonons with Bose–Einstein statistics and use them to explain why the specific heat of a solid goes as $T^3$ at low temperature and saturates at $3Nk_B$ at high temperature.",
      encounters=[c1, c2, c3, c4, boss1])
